#!/usr/bin/env node
// paperfence guard hook. Generated by `paperfence harden`; edit policy.json, not this file.
// Runs on PreToolUse. Exit 2 blocks the call and the stderr line is what the agent sees.
// No dependencies. Works in "type": "module" repos because it is .cjs.
"use strict";
const fs = require("fs");
const path = require("path");
const { execFileSync } = require("child_process");

// Never execSync in here. The arguments are paths the agent chose, and a shell
// would run whatever is inside $(...). `git cat-file -e HEAD:"x$(rm -rf .claude).txt"`
// deleted the enforcement configuration while checking whether a file existed.
function git(args) {
  return execFileSync("git", args, { cwd, stdio: ["ignore", "pipe", "ignore"] }).toString();
}

const policy = JSON.parse(fs.readFileSync(path.join(__dirname, "policy.json"), "utf8"));
const input = JSON.parse(fs.readFileSync(0, "utf8"));
const event = input.hook_event_name || "PreToolUse";
const tool = input.tool_name || "";
const ti = input.tool_input || {};
const cwd = input.cwd || process.cwd();
const session = String(input.session_id || "nosession").replace(/[^\w-]/g, "").slice(0, 40);
const stateFile = path.join(cwd, ".claude", ".paperfence-session-" + session + ".json");

function block(msg) {
  process.stderr.write("paperfence: " + msg + "\n");
  process.exit(2);
}
function rel(p) {
  if (!p) return "";
  const abs = path.isAbsolute(p) ? p : path.join(cwd, p);
  return path.relative(cwd, abs).split(path.sep).join("/");
}
function under(p, dir) {
  return p === dir || p.startsWith(dir + "/");
}
function readState() {
  try {
    return JSON.parse(fs.readFileSync(stateFile, "utf8"));
  } catch {
    return {};
  }
}
function writeState(s) {
  try {
    fs.mkdirSync(path.dirname(stateFile), { recursive: true });
    fs.writeFileSync(stateFile, JSON.stringify(s));
  } catch {}
}
function currentBranch() {
  try {
    return git(["rev-parse", "--abbrev-ref", "HEAD"]).trim();
  } catch {
    return "";
  }
}
const escapeRe = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");

// Split the way Claude Code does: every separator outside quotes, plus subshells,
// command substitutions, and the bodies of sh -c / bash -c.
function splitTop(cmd) {
  const out = [];
  let cur = "", inS = false, inD = false, depth = 0;
  for (let i = 0; i < cmd.length; i++) {
    const c = cmd[i];
    if (inS) { cur += c; if (c === "'") inS = false; continue; }
    if (inD) { cur += c; if (c === "\\") { cur += cmd[++i] || ""; continue; } if (c === '"') inD = false; continue; }
    if (c === "\\") { cur += c + (cmd[++i] || ""); continue; }
    if (c === "'") { inS = true; cur += c; continue; }
    if (c === '"') { inD = true; cur += c; continue; }
    if (c === "(" || c === "{") depth++;
    if (c === ")" || c === "}") depth = Math.max(0, depth - 1);
    if (depth === 0) {
      const m = /^(\|\||&&|\|&|;;|;|\||&|\n)/.exec(cmd.slice(i));
      if (m) { if (cur.trim()) out.push(cur.trim()); cur = ""; i += m[0].length - 1; continue; }
    }
    cur += c;
  }
  if (cur.trim()) out.push(cur.trim());
  return out;
}
function subshellBodies(seg) {
  const out = [];
  let inS = false, inD = false;
  for (let i = 0; i < seg.length; i++) {
    const c = seg[i];
    if (!inD && c === "'") { inS = !inS; continue; }
    if (inS) continue;
    if (c === "\\") { i++; continue; }
    if (c === '"') { inD = !inD; continue; }
    if (seg.startsWith("$(", i) || (!inD && c === "(" && (i === 0 || /\s/.test(seg[i - 1])))) {
      const start = c === "$" ? i + 2 : i + 1;
      let depth = 1, j = start, s2 = false, d2 = false;
      while (j < seg.length && depth > 0) {
        const ch = seg[j];
        if (s2) { if (ch === "'") s2 = false; }
        else if (d2) { if (ch === "\\") j++; else if (ch === '"') d2 = false; }
        else if (ch === "'") s2 = true; else if (ch === '"') d2 = true;
        else if (ch === "(") depth++; else if (ch === ")") depth--;
        j++;
      }
      const inner = seg.slice(start, j - 1).trim();
      if (inner) out.push(inner);
      i = j - 1;
      continue;
    }
    if (c === "`") {
      const j = seg.indexOf("`", i + 1);
      if (j > i) { const inner = seg.slice(i + 1, j).trim(); if (inner) out.push(inner); i = j; }
    }
  }
  return out;
}
function segments(cmd, depth = 0) {
  if (depth > 6) return [];
  const out = [];
  for (const seg of splitTop(cmd)) {
    out.push(seg);
    for (const inner of subshellBodies(seg)) out.push(...segments(inner, depth + 1));
    // `{ rm -rf build; }` parses as a segment whose program is `{`, so nothing
    // inside it was matched. A brace group is a list of commands.
    if (/^\{\s/.test(seg)) {
      const body = seg.replace(/^\{\s*/, "").replace(/\s*\}\s*;?\s*$/, "");
      if (body && body !== seg) out.push(...segments(body, depth + 1));
    }
    // sh -c '...' / bash -lc "..." : the body is a command too. The flag may be
    // combined with others, so -lc, -ec and -xc all carry a command.
    const p = parseProg(seg);
    if (/^(sh|bash|zsh|dash|ksh|ash|busybox)$/.test(p.prog)) {
      const ci = p.argv.findIndex((a) => /^-[a-zA-Z]*c$/.test(a) || a === "--command");
      if (ci !== -1 && p.argv[ci + 1]) out.push(...segments(p.argv[ci + 1], depth + 1));
    }
    // env/xargs/timeout and friends wrap a command; so does `su -c`.
    if (/^(env|nohup|timeout|stdbuf|setsid|nice|ionice|script|doas|sudo)$/.test(p.prog)) {
      const rest = p.argv.filter((a) => !a.startsWith("-") && !/^\w+=/.test(a));
      if (rest.length) out.push(...segments(rest.join(" "), depth + 1));
    }
  }
  return out;
}

// Quote-stripped words of one segment.
function wordsOf(seg) {
  const out = [];
  let cur = "";
  let started = false;
  for (let i = 0; i < seg.length; i++) {
    const c = seg[i];
    if (c === "'") {
      const j = seg.indexOf("'", i + 1);
      cur += seg.slice(i + 1, j === -1 ? seg.length : j);
      started = true;
      i = j === -1 ? seg.length : j;
    } else if (c === '"') {
      let j = i + 1;
      while (j < seg.length && seg[j] !== '"') {
        if (seg[j] === "\\" && j + 1 < seg.length) j++;
        cur += seg[j++];
      }
      started = true;
      i = j;
    } else if (c === "\\" && i + 1 < seg.length) {
      cur += seg[++i];
      started = true;
    } else if (/\s/.test(c)) {
      if (started) out.push(cur);
      cur = "";
      started = false;
    } else {
      cur += c;
      started = true;
    }
  }
  if (started) out.push(cur);
  return out;
}

// "VAR=1 command env sudo /usr/bin/prog args" -> { prog: "prog", args: "args", argv: [...] }
const WRAPPERS = new Set(["command", "env", "sudo", "nice", "nohup", "time", "exec", "xargs", "doas", "stdbuf", "timeout"]);
const OPT_WITH_VALUE = { nice: /^-n$/, env: /^-[uCS]$/, sudo: /^-[ugh]$/, timeout: /^-[sk]$/, stdbuf: /^-[oei]$/ };
function parseProg(seg) {
  const w = wordsOf(seg);
  let k = 0;
  while (k < w.length && /^[A-Za-z_][A-Za-z0-9_]*=/.test(w[k])) k++;
  for (;;) {
    const name = (w[k] || "").split("/").pop();
    if (!WRAPPERS.has(name)) break;
    if (name === "command" && (w[k + 1] || "").startsWith("-")) break; // command -v: a lookup
    k++;
    while (k < w.length && (w[k].startsWith("-") || (name === "timeout" && /^\d/.test(w[k])))) {
      const opt = w[k++];
      if (OPT_WITH_VALUE[name] && OPT_WITH_VALUE[name].test(opt)) k++;
    }
  }
  const argv = w.slice(k + 1);
  return { prog: (w[k] || "").split("/").pop(), args: argv.join(" "), argv };
}

// git with global options stripped: "git -C . -c x=y push origin main" -> { sub: "push", args: "origin main" }
function parseGit(seg) {
  const { prog, argv } = parseProg(seg);
  if (prog !== "git") return null;
  let i = 0;
  while (i < argv.length) {
    const t = argv[i];
    if (t === "-C" || t === "-c") i += 2;
    else if (/^(--git-dir=|--work-tree=|--no-pager$|-p$|--paginate$|--literal-pathspecs$)/.test(t)) i += 1;
    else break;
  }
  if (!argv[i]) return null;
  return { sub: argv[i], args: argv.slice(i + 1).join(" "), argv: argv.slice(i + 1) };
}

const secretFileRe = (f) => "(?:\\./|\\S*/)?" + escapeRe(f);

// A test is "existing" if it is committed in HEAD. Files the agent created this
// session (untracked or staged-but-uncommitted) are its own to fix or remove.
// Outside a git repo, fall back to "exists on disk".
const committedCache = new Map();
function committed(relPath) {
  if (!relPath) return false;
  if (committedCache.has(relPath)) return committedCache.get(relPath);
  let result;
  try {
    git(["cat-file", "-e", "HEAD:" + relPath]);
    result = true;
  } catch (e) {
    let inRepo = true;
    try { git(["rev-parse", "--is-inside-work-tree"]); } catch { inRepo = false; }
    result = inRepo ? false : fs.existsSync(path.join(cwd, relPath));
  }
  committedCache.set(relPath, result);
  return result;
}

// ---------- PostToolUse: remember that a required step actually ran ----------
if (event === "PostToolUse") {
  if (tool === "Bash" && policy.requireBefore.length) {
    const cmd = String(ti.command || "");
    const resp = input.tool_response;
    const text = typeof resp === "string" ? resp : JSON.stringify(resp || "");
    const failed = /"exit_code":\s*[1-9]|"interrupted":\s*true|command failed|exit code [1-9]/i.test(text) || (resp && typeof resp === "object" && resp.exit_code && resp.exit_code !== 0);
    const backgrounded = /(^|\s)&\s*$/.test(cmd) || (resp && typeof resp === "object" && resp.backgroundTaskId);
    // Only the whole command counts. "false && npm test || true" proves nothing.
    const top = splitTop(cmd);
    if (!failed && !backgrounded && top.length === 1) {
      const state = readState();
      const { prog, args } = parseProg(top[0]);
      const normalized = (prog + (args ? " " + args : "")).trim();
      for (const req of policy.requireBefore) {
        if (normalized !== req.command && !normalized.startsWith(req.command + " ")) continue;
        // `npm test --help` prints usage and tests nothing, so it must not earn
        // credit for having run the suite.
        const extra = normalized.slice(req.command.length);
        if (/(^|\s)(--help|-h|--version|-v|--dry-run|--list(-tests)?|--listTests)(\s|$)/.test(extra)) continue;
        state["ran:" + req.command] = Date.now();
      }
      writeState(state);
    }
  }
  process.exit(0);
}

// ---------- the hook and its policy are off limits ----------
const SELF = [".claude/hooks/", ".claude/settings.json", ".claude/settings.local.json", ".claude/.paperfence-session"];
function touchesSelf(p) {
  const n = p.replace(/\/+$/, "");
  return n === ".claude" || n === ".claude/hooks" || SELF.some((x) => n === x || n.startsWith(x) || n.endsWith("/" + x) || n.includes("/" + x));
}

// ---------- what decides which tests run ----------
// Deleting an assertion is the obvious way to make a suite green. Pointing the
// runner somewhere else is the quiet one. These files select tests; the tests
// themselves are protected separately above.
function isTestControl(p) {
  const base = p.split("/").pop() || "";
  return (
    /^(vitest|jest|karma|ava|playwright|cypress|nightwatch|wdio)\.config\.[cm]?[jt]s$/.test(base) ||
    base === "jest.config.json" ||
    /^\.mocharc\.(ya?ml|json|js|cjs)$/.test(base) ||
    /^(pytest\.ini|tox\.ini|setup\.cfg|conftest\.py|noxfile\.py|\.rspec)$/.test(base) ||
    /^\.github\/workflows\//.test(p) ||
    p === ".gitlab-ci.yml" ||
    p === ".circleci/config.yml" ||
    p === "azure-pipelines.yml"
  );
}

// The test script in package.json, as written. Changing it is how a suite goes
// green without a single test file being touched.
function testScript() {
  try {
    return JSON.parse(fs.readFileSync(path.join(cwd, "package.json"), "utf8")).scripts?.test ?? null;
  } catch {
    return null;
  }
}
const TEST_SCRIPT_BEFORE = policy.protectedTestPaths.length ? testScript() : null;

// An edit to package.json is ordinary work unless it lands on the test script.
// We look at the edit's own text rather than guessing from the file path.
function changesTestScript(input) {
  if (TEST_SCRIPT_BEFORE === null) return false;
  const texts = [];
  if (typeof input.content === "string") texts.push(input.content);
  if (typeof input.new_string === "string") texts.push(input.new_string);
  if (typeof input.old_string === "string") texts.push(input.old_string);
  if (Array.isArray(input.edits)) for (const e of input.edits) { if (e && typeof e === "object") { if (typeof e.old_string === "string") texts.push(e.old_string); if (typeof e.new_string === "string") texts.push(e.new_string); } }
  if (!texts.length) return true; // an edit we cannot read: assume it could
  const whole = texts.join("\n");
  if (whole.includes(TEST_SCRIPT_BEFORE)) return true;
  return /"test"\s*:/.test(whole);
}

// ---------- file tools ----------
if (["Read", "Edit", "Write", "MultiEdit", "NotebookEdit"].includes(tool)) {
  const p = rel(ti.file_path || ti.path || ti.notebook_path || "");
  for (const s of policy.secretFiles) {
    if (p === s || p.endsWith("/" + s)) block("reading " + s + " is not allowed");
  }
  if (tool !== "Read") {
    if (touchesSelf(p)) block("the paperfence hook, its policy and settings.json are not editable by the agent");
    // "Do not weaken tests" is about tests that were already committed. A test the agent
    // created this session is its own to fix; adding a new test file is ordinary work.
    if (committed(p)) {
      for (const d of policy.protectedTestPaths) {
        if (under(p, d)) block("editing existing tests under " + d + "/ is not allowed; fix the code instead (new test files are fine)");
      }
      if (policy.protectedTestPaths.length && /\.(test|spec)\.[cm]?[jt]sx?$|_test\.(go|py|rb)$|^test_.*\.py$/.test(p)) block("editing existing test files is not allowed; fix the code instead (new test files are fine)");
    }
    // Unlike a test file, a *new* runner config is not ordinary work: adding
    // one that excludes the failing test is exactly the move being prevented.
    if (policy.protectedTestPaths.length && isTestControl(p)) {
      block("writing " + p + " is not allowed: it decides which tests run, and changing it makes the suite pass without fixing anything");
    }
    if (policy.protectedTestPaths.length && TEST_SCRIPT_BEFORE !== null && p === "package.json" && changesTestScript(ti)) {
      block("changing the test script in package.json is not allowed: it decides which tests run");
    }
    for (const d of policy.forbiddenPaths) {
      if (under(p, d)) block("editing " + d + "/ is not allowed");
    }
    if (policy.allowedPaths.length && !policy.allowedPaths.some((d) => under(p, d)) && !p.startsWith(".claude/")) {
      block("edits are only allowed under " + policy.allowedPaths.join(", "));
    }
  }
}

// ---------- shell ----------
if (tool === "Bash") {
  const cmd = String(ti.command || "");
  const branch = policy.protectedBranches.length ? currentBranch() : "";

  for (const s of segments(cmd)) {
    const { prog, args, argv } = parseProg(s);
    const git = parseGit(s);
    const scripty = /^(python3?|node|ruby|perl|php|deno|bun)$/.test(prog);
    const scriptText = scripty ? argv.join(" ") : "";

    // protected branches
    for (const b of policy.protectedBranches) {
      const bRe = escapeRe(b);
      if (git && git.sub === "push") {
        if (git.argv.some((a) => new RegExp("(^|:|\\+)(refs/heads/)?" + bRe + "$").test(a))) block("pushing to " + b + " is not allowed; push a branch and open a pull request");
        // bare "git push", "git push origin", "git push -u origin HEAD": whatever is checked out
        const positional = git.argv.filter((a) => !a.startsWith("-"));
        const refspec = positional[1];
        if ((positional.length <= 1 || refspec === "HEAD") && branch === b) block("pushing " + b + " is not allowed; push a branch and open a pull request");
      }
      if (git && git.sub === "commit" && branch === b) block("committing on " + b + " is not allowed; create a branch first");
      if (git && (git.sub === "checkout" || git.sub === "switch") && git.argv.includes(b) && /\bgit\b[^|;&]*\bcommit\b/.test(cmd)) block("committing on " + b + " is not allowed");
      if (git && (git.sub === "merge" || git.sub === "rebase") && branch === b) block("changing " + b + " locally is not allowed; work on a branch");
    }

    // force push
    if (policy.blockForcePush && git && git.sub === "push") {
      if (git.argv.some((a) => /^(--force|--force-with-lease(=.*)?|--force-if-includes|-[a-zA-Z]*f[a-zA-Z]*)$/.test(a) || a.startsWith("+"))) block("force push is not allowed");
    }

    // destructive
    if (policy.blockDestructive) {
      if (prog === "rm" && argv.some((a) => /^-[a-zA-Z]*[rR]/.test(a) || a === "--recursive")) block("rm -r is not allowed");
      if (git && git.sub === "reset" && git.argv.includes("--hard")) block("git reset --hard is not allowed");
      if (git && git.sub === "clean" && git.argv.some((a) => /^-[a-zA-Z]*f/.test(a) || a === "--force") && !git.argv.some((a) => /^-[a-zA-Z]*n/.test(a) || a === "--dry-run")) block("git clean -f is not allowed");
      if (git && (git.sub === "checkout" || git.sub === "restore") && /(^|\s)(--\s+)?\.\s*$|(^|\s)--\s+\./.test(git.args)) block("discarding all changes is not allowed");
      if (git && git.sub === "branch" && /(^|\s)-[a-zA-Z]*D/.test(git.args)) block("force-deleting branches is not allowed");
      if (prog === "find" && /(^|\s)-delete(\s|$)/.test(args)) block("find -delete is not allowed");
      if (/\b(drop\s+(table|database|schema)|truncate\s+table)\b/i.test(s)) block("destructive SQL is not allowed");
      if (/(^|\s)>\s*\/dev\/(sd|disk|nvme)/.test(s) || prog === "mkfs" || prog === "dd") block("disk-level commands are not allowed");
    }

    // dependencies
    if (policy.blockInstall) {
      const pm = /^(npm|pnpm|yarn|bun)$/.test(prog) ? prog : null;
      if (pm) {
        const positional = argv.filter((a) => !a.startsWith("-"));
        const optValues = new Set();
        argv.forEach((a, i) => { if (/^--prefix$|^-C$|^--cwd$|^-w$|^--workspace$|^--filter$/.test(a) && argv[i + 1]) optValues.add(argv[i + 1]); });
        const pos = positional.filter((a) => !optValues.has(a));
        if (/^(install|i|add)$/.test(pos[0] || "") && pos.length > 1) block("adding dependencies requires approval");
      }
      if (/^pip3?$/.test(prog)) {
        const m = /^install\b([\s\S]*)$/.exec(args.trim());
        if (m) {
          const rest = m[1].replace(/(^|\s)-r\s+\S+/g, " ").replace(/(^|\s)-{1,2}[\w-]+(=\S+)?/g, " ").trim();
          if (rest) block("adding dependencies requires approval");
        }
      }
      if ((prog === "cargo" || prog === "uv" || prog === "poetry") && /^add\b/.test(args.trim())) block("adding dependencies requires approval");
      if (prog === "go" && /^get\s+\S/.test(args.trim())) block("adding dependencies requires approval");
    }

    // network
    if (policy.blockNetwork) {
      if (/^(curl|wget|wget2|nc|ncat|netcat|ssh|scp|sftp|rsync|ftp|lftp|telnet|socat|http|https|httpie|xh|aria2c|lwp-request)$/.test(prog) && !/127\.0\.0\.1|localhost/.test(args)) block("outbound network commands are not allowed");
      // A name lookup is a channel: the data goes out in the label being resolved.
      if (/^(dig|nslookup|host)$/.test(prog)) block("name lookups are not allowed: a hostname carries whatever is put in it");
      // A remote added mid-run, or a push straight to a URL, is exfiltration
      // with a different verb.
      if (git && git.sub === "remote" && git.argv.includes("add") && git.argv.some((a) => /^(https?:\/\/|git@|ssh:\/\/)/.test(a))) block("adding a remote to push to is not allowed");
      if (git && git.sub === "push" && git.argv.some((a) => /^(https?:\/\/|git@|ssh:\/\/)/.test(a))) block("pushing to a URL instead of a configured remote is not allowed");
      // Looking for "localhost" anywhere in the text let a URL smuggle the
      // exemption in its path: https://example.com/localhost was treated as
      // loopback. Check the host of each URL instead.
      const urls = scriptText.match(/https?:\/\/[^\s"'`)]+/g) || [];
      const nonLoopback = urls.filter((u) => {
        const host = (u.replace(/^https?:\/\//, "").split(/[/?#]/)[0] || "").split("@").pop().split(":")[0];
        return host && host !== "127.0.0.1" && host !== "localhost" && host !== "::1" && host !== "0.0.0.0";
      });
      const networkCall = /(urllib|requests\.|http\.client|\bfetch\s*\(|https?\.(request|get)|net\.connect|socket\.|WebSocket|XMLHttpRequest|axios|got\()/.test(scriptText);
      if (scripty && networkCall && (nonLoopback.length > 0 || urls.length === 0)) block("outbound network from scripts is not allowed");
      if (scripty && nonLoopback.length > 0) block("outbound network from scripts is not allowed");
    }

    // secrets
    for (const f of policy.secretFiles) {
      const fRe = secretFileRe(f);
      const readers = /^(cat|less|more|head|tail|bat|xxd|od|hexdump|strings|base64|base32|uuencode|gzip|zcat|grep|egrep|fgrep|rg|ag|awk|gawk|mawk|sed|cut|paste|join|sort|uniq|wc|nl|tac|rev|fold|split|expand|column|diff|cmp|tr|jq|yq|envsubst|md5sum|shasum|sha256sum|openssl|cp|install|tee|source|\.|dotenv|python3?|node|ruby|perl|php|deno|bun|sh|bash|zsh|env|xargs|timeout|nohup|stdbuf|script)$/;
      const named = new RegExp("(^|[\\s'\"(=<>])(\\.\\/)?" + fRe + "([\\s'\")>;&|]|$)");
      if (readers.test(prog) && named.test(args)) block("reading " + f + " is not allowed");
      if (new RegExp("<\\s*(\\.\\/)?" + fRe + "(\\s|$|;|&)").test(s)) block("reading " + f + " is not allowed");
      if (new RegExp("(readFileSync|readFile|open|read_text|load_dotenv)\\s*\\(\\s*['\"](\\.\\/)?" + fRe + "['\"]").test(s)) block("reading " + f + " is not allowed");
      // A shell loop or a process substitution reads the file with no reader
      // program on the line at all.
      if (/\b(read\s+(-\w+\s+)*\w|mapfile|readarray)\b/.test(s) && named.test(s)) block("reading " + f + " is not allowed");
      if (/<\(|\$\(<\s*/.test(s) && named.test(s)) block("reading " + f + " is not allowed");
    }

    // the hook itself
    const shellWriters = /^(rm|mv|cp|unlink|tee|touch|truncate|install|ln|chmod)$/;
    const editsInPlace = /^(sed|perl)$/.test(prog) && /(^|\s)-i/.test(args);
    const writeTargets = [...(s.match(/(?:^|\s)\d?>>?\s*(\S+)/g) || []).map((m) => m.replace(/^\s*\d?>>?\s*/, ""))];
    let argPaths = argv.filter((a) => a && !a.startsWith("-"));
    // Only the destination matters for what gets written. But `mv` also removes
    // its source, so moving the hook directory away deleted the guard while the
    // guard said yes.
    const movesAway = prog === "mv" || prog === "rename";
    if ((prog === "cp" || prog === "install" || prog === "ln") && argPaths.length > 1) argPaths = argPaths.slice(-1); // destination only
    if (movesAway && argPaths.some((a) => touchesSelf(rel(a)))) block("moving the paperfence hook, its policy or settings.json is not allowed");
    const shellTouches = (pred) => (shellWriters.test(prog) || editsInPlace) && argPaths.some(pred) || writeTargets.some(pred);
    if (shellTouches((a) => touchesSelf(rel(a)))) block("the paperfence hook, its policy and settings.json are not editable by the agent");
    if (prog === "rm" && argv.some((a) => !a.startsWith("-") && touchesSelf(rel(a)))) block("the paperfence hook, its policy and settings.json are not editable by the agent");
    if (scripty && /\.claude\/(hooks|settings|\.paperfence)/.test(scriptText) && /(writeFile|appendFile|unlink|rm|rename|open\([^)]*['"][wa]|chmod)/.test(scriptText)) block("the paperfence hook, its policy and settings.json are not editable by the agent");

    // scope
    for (const d of policy.forbiddenPaths) {
      if (shellTouches((a) => under(rel(a), d))) block("editing " + d + "/ is not allowed");
      if (scripty && new RegExp("(writeFile|appendFile|unlink|rm|rename|open\\([^)]*['\"][wa])[^;]*" + escapeRe(d) + "/").test(scriptText)) block("editing " + d + "/ from a script is not allowed");
    }
    if (policy.allowedPaths.length) {
      if (shellTouches((a) => { const r = rel(a); return r && !r.startsWith("..") && !policy.allowedPaths.some((d) => under(r, d)) && !r.startsWith(".claude/"); })) block("edits are only allowed under " + policy.allowedPaths.join(", "));
    }

    // tests
    for (const d of policy.protectedTestPaths) {
      const isTestPath = (r) => r === d || r.startsWith(d + "/") || /\.(test|spec)\.[cm]?[jt]sx?$|_test\.(go|py|rb)$/.test(r);
      const existing = (a) => { const r = rel(a); return isTestPath(r) && committed(r); };
      // Removing, moving or overwriting an existing test is blocked. Creating a new one is not.
      if (/^(rm|unlink|truncate)$/.test(prog) && argv.some((a) => !a.startsWith("-") && (rel(a) === d || existing(a)))) block("removing tests under " + d + "/ is not allowed; fix the code instead");
      if (/^(mv|cp|install|ln|tee)$/.test(prog)) {
        const paths = argv.filter((a) => !a.startsWith("-"));
        if (paths.some(existing)) block("overwriting or moving existing tests under " + d + "/ is not allowed");
      }
      if (scripty && new RegExp("(writeFile|unlink|rm|rename|open\\([^)]*['\"][wa])[^;]*" + escapeRe(d) + "/").test(scriptText)) block("changing tests from a script is not allowed");
      if (git && git.sub === "rm" && git.argv.some(existing)) block("removing tests under " + d + "/ is not allowed");
      if (/^(sed|perl)$/.test(prog) && /(^|\s)-i\b/.test(args) && argv.some(existing)) block("editing existing tests under " + d + "/ is not allowed");
      for (const t of writeTargets) if (existing(t)) block("overwriting existing tests under " + d + "/ from the shell is not allowed");
    }

    // what decides which tests run
    if (policy.protectedTestPaths.length) {
      if (shellTouches((a) => isTestControl(rel(a)))) block("changing a file that decides which tests run is not allowed");
      if (/^(rm|unlink|truncate|mv)$/.test(prog) && argv.some((a) => !a.startsWith("-") && isTestControl(rel(a)))) block("removing or moving a file that decides which tests run is not allowed");
      if (scripty && /(writeFile|appendFile|unlink|rename|open\([^)]*['"][wa])/.test(scriptText) && /(package\.json|jest\.config|vitest\.config|mocharc|pytest\.ini|conftest|workflows\/)/.test(scriptText)) {
        block("changing a file that decides which tests run, from a script, is not allowed");
      }
      // `npm pkg set scripts.test=...` edits package.json without an Edit tool call.
      if (prog === "npm" && /\bpkg\b/.test(args) && /scripts\.test/.test(args)) block("changing the test script is not allowed: it decides which tests run");
      if (/^(sed|perl)$/.test(prog) && /(^|\s)-i\b/.test(args) && argv.some((a) => rel(a) === "package.json" || isTestControl(rel(a)))) {
        block("editing a file that decides which tests run, in place, is not allowed");
      }
      for (const t of writeTargets) if (isTestControl(rel(t)) || rel(t) === "package.json") block("overwriting a file that decides which tests run is not allowed");
    }

    // ask-first
    for (const a of policy.askFirstCommands) {
      const aProg = a.split(/\s+/)[0];
      const aRest = a.split(/\s+/).slice(1).join(" ");
      if (prog === aProg && (aRest === "" || args.trim() === aRest || args.trim().startsWith(aRest + " ") || new RegExp("(^|\\s)" + escapeRe(aRest) + "(\\s|$)").test(args))) {
        block('"' + a + '" requires a human to approve it first');
      }
    }

    // required step before the action it actually gates (recorded by the
    // PostToolUse half, above). "lint before pushing" is not a rule about
    // committing, so gating the wrong verb would block allowed work and let
    // the forbidden work through.
    if (policy.requireBefore.length && git) {
      const state = readState();
      const verb = git.sub === "commit" ? "commit" : git.sub === "push" ? "push" : null;
      if (verb) {
        for (const req of policy.requireBefore) {
          // Exactly the action the rule names, nothing more. Gating a push on a
          // rule that says "before committing" blocks pushing commits that were
          // made before the rule existed, which is ordinary work.
          if (req.action !== verb) continue;
          const t = state["ran:" + req.command];
          if (!t || Date.now() - t > 30 * 60 * 1000) block('run "' + req.command + '" before ' + (verb === "push" ? "pushing" : "committing") + ' (not seen in the last 30 minutes)');
        }
      }
    }
  }
}

if (tool === "WebFetch" && policy.blockNetwork) {
  const url = String(ti.url || "");
  if (!/127\.0\.0\.1|localhost/.test(url)) block("fetching external URLs is not allowed");
}

process.exit(0);
